{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Fimasartan, the closest structural analogue sharing the 2-butylimidazole/N-benzyl ARB scaffold, has an absolute oral bioavailability of 18.6% in healthy volunteers, below the 20% threshold; this supports a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Telmisartan, a carboxylic-acid ARB, has an absolute bioavailability of 43%, above the threshold; however, its benzimidazole/biphenyl structure is less transferable to the query's imidazole/para-carboxybenzyl and thiophene-acrylic acid architecture.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Olmesartan, another butylimidazole ARB, has about 26% absolute bioavailability, only marginally above the threshold; its biphenyl tetrazole and prodrug-related absorption differ from the query's dicarboxylic acid structure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is eprosartan, a dicarboxylic acid ARB with a thiophene-acrylic acid side chain. Its closest retrieved analogue, fimasartan, has absolute oral bioavailability of 18.6% in humans, below the 20% threshold, and the additional polar carboxylates in the query are expected to further limit intestinal permeability. High-F ARBs such as telmisartan and olmesartan are structurally less transferable. Therefore F<20% is predicted.",
  "evidence_gaps": [
    "No direct experimental record for the query molecule (eprosartan) in the retrieved evidence; the closest analogue fimasartan has only 0.26 Morgan similarity.",
    "The impact of the two carboxylic acid groups on permeability is inferred rather than directly measured in the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

